# Generated by tools/packgen/banking/make_packs.py from snippets/trading/trade_vs_peers.py there. Edit that source, not this file.
# title: The trade among its peers
# description: Every valuation of the same PRODUCT_TYPE across the source systems (drishti.search_async over the risk engine's trade valuations, TVAL): NOTIONAL, MTM, PNL_1D and MTM as a share of notional; where this trade ranks (percentiles) in each, the peers by PORTFOLIO and CURRENCY, and a scatter of MTM against notional with this trade marked.
# kinds: trade

import pandas as pd

doc = view.doc
me_id = f"TVAL-{doc['TRADE_ID']}"
peers = await drishti.search_async(f"TVAL where PRODUCT_TYPE = '{doc['PRODUCT_TYPE']}' and DESK != '' limit 1000")
if me_id not in set(peers["ID"]):                     # the trade itself may not match: add its own valuation
    peers = pd.concat([peers, pd.DataFrame([await drishti.get_async("trade-valuation", me_id)]).assign(ID=me_id)], ignore_index=True)
for col in ["NOTIONAL", "MTM", "PNL_1D"]:
    peers[col] = pd.to_numeric(peers[col], errors="coerce")
peers["MTM % NOTIONAL"] = peers["MTM"] / peers["NOTIONAL"].where(peers["NOTIONAL"] != 0) * 100
me = peers[peers["ID"] == me_id]

rank = []
for col in ["NOTIONAL", "MTM", "PNL_1D", "MTM % NOTIONAL"]:
    rank.append({"measure": col, "this trade": me[col].iloc[0], "peer median": peers[col].median(),
                 "peer min": peers[col].min(), "peer max": peers[col].max(),
                 "percentile": (peers[col] < me[col].iloc[0]).mean() * 100})
show(pd.DataFrame(rank), title=f"{view.id} among {len(peers)} {doc['PRODUCT_TYPE']} trades")
show(peers.groupby(["SOURCE_SYSTEM", "PORTFOLIO", "CURRENCY"]).agg(trades=("ID", "size"), NOTIONAL=("NOTIONAL", "sum"), MTM=("MTM", "sum"),
                                                                     PNL_1D=("PNL_1D", "sum")).reset_index(), title="Peers by system, portfolio and currency")
chart(peers.assign(who=["this trade" if i == me_id else "peer" for i in peers["ID"]]),
      kind="scatter", x="NOTIONAL", y="MTM", title=f"MTM against notional: {doc['PRODUCT_TYPE']}")
